package main

import (
	"fmt"
	"sort"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	var mu sync.Mutex
	var out []string
	for _, v := range []string{"a", "b", "c"} {
		wg.Add(1)
		go func(v string) { // v passed in: each goroutine gets its own
			defer wg.Done()
			mu.Lock()
			out = append(out, v)
			mu.Unlock()
		}(v)
	}
	wg.Wait()
	sort.Strings(out)
	fmt.Println(out)
	// Output: [a b c]
}

