package main

import "fmt"

// n escapes to the heap because the returned closure outlives adder.
func adder() func(int) int {
	n := 0
	return func(d int) int { n += d; return n }
}

func main() {
	add := adder()
	fmt.Println(add(3), add(4)) // n survives after adder returned
	// Output: 3 7
}

