package solution

// Memoize returns a closure that caches fn's results per input.
func Memoize(fn func(int) int) func(int) int {
	cache := make(map[int]int) // captured by reference; private to the closure
	return func(n int) int {
		if v, ok := cache[n]; ok { // cache hit
			return v
		}
		v := fn(n)    // miss: compute once
		cache[n] = v  // remember for next time
		return v
	}
}

