// Compose returns a function that applies fns left-to-right:
// Compose(f1, f2, f3)(x) == f3(f2(f1(x))). Empty -> identity.
func Compose(fns ...func(int) int) func(int) int {
	return func(x int) int { // closure captures fns
		for _, f := range fns { // left-to-right: f1, then f2, ...
			x = f(x) // thread the running value forward
		}
		return x // no fns -> returns x unchanged (identity)
	}
}

// Every returns a function that invokes fn on its 1st call and every
// nth call thereafter, using a captured counter for state.
func Every(n int, fn func()) func() {
	if n < 1 {
		n = 1
	}
	count := 0 // captured by reference; persists across calls
	return func() {
		if count%n == 0 { // fires on call 0, n, 2n, ... (the 1st, (n+1)th, ...)
			fn()
		}
		count++
	}
}
